import{_ as e,o as a,c as d,a5 as o}from"./chunks/framework.B5tqjWbr.js";const m=JSON.parse('{"title":"示例 3：启用逆变器非线性建模","description":"","frontmatter":{"date":"2026-06-08T00:00:00.000Z","section":"电机控制","chapter":"simulation","chapterTitle":"仿真与调试","chapterOrder":10,"category":"仿真与调试","source":"motor","visibility":"public","title":"示例 3：启用逆变器非线性建模","tags":["motor-control"],"status":"learning","summary":"观察死区效应和逆变器非线性对电流波形的影响。","navGroup":"实践与验证","navGroupOrder":40},"headers":[],"relativePath":"content/motor/simulation/code-examples/03-enable-inverter-nonlinearity/README.md","filePath":"content/motor/simulation/code-examples/03-enable-inverter-nonlinearity/README.md","lastUpdated":1783096495000}'),r={name:"content/motor/simulation/code-examples/03-enable-inverter-nonlinearity/README.md"};function i(l,t,n,c,s,h){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="示例-3-启用逆变器非线性建模" tabindex="-1">示例 3：启用逆变器非线性建模 <a class="header-anchor" href="#示例-3-启用逆变器非线性建模" aria-label="Permalink to &quot;示例 3：启用逆变器非线性建模&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>观察死区效应和逆变器非线性对电流波形的影响。</p><h2 id="四种逆变器模型" tabindex="-1">四种逆变器模型 <a class="header-anchor" href="#四种逆变器模型" aria-label="Permalink to &quot;四种逆变器模型&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>宏值</th><th>模型</th><th>原理</th><th>适用场景</th></tr></thead><tbody><tr><td>0</td><td>理想逆变器</td><td>无压降，给定电压直接输出</td><td>理论验证、控制算法调试</td></tr><tr><td>1</td><td>Sul1996</td><td>基于死区时间+管压降的数学模型</td><td>通用仿真，参数可调</td></tr><tr><td>2</td><td>Sigmoid 拟合</td><td>用 S 型曲线拟合实验数据</td><td>匹配特定逆变器实测数据</td></tr><tr><td>3</td><td>LUT 查表（插值）</td><td>对测量 V-I 曲线插值</td><td>最精确，需要实测数据</td></tr><tr><td>4</td><td>LUT 查表（索引）</td><td>直接按索引查表</td><td>同上但更快</td></tr></tbody></table></div><h2 id="要改什么" tabindex="-1">要改什么 <a class="header-anchor" href="#要改什么" aria-label="Permalink to &quot;要改什么&quot;">​</a></h2><ol><li></li></ol><p><code>ACMSim.h</code> 第 9 行：<code>#define __INVERTER_NONLINEARITY 0</code> → 改为 1/2/3/4 2. <code>user_config.yaml</code>：<code>user.mode_select_synchronous_motor: 49</code> 3. 运行后观察 iD/iQ 子图的电流波形</p><h2 id="预期效果" tabindex="-1">预期效果 <a class="header-anchor" href="#预期效果" aria-label="Permalink to &quot;预期效果&quot;">​</a></h2><ul><li>模式 0（理想）：电流波形光滑正弦，无畸变</li><li>模式 1-4：电流过零点出现钳位效应（平顶/平底），THD 增大</li><li>低速轻载时畸变最明显（电流小 → 死区占比大）</li></ul><h2 id="关键参数-模式-1-sul1996" tabindex="-1">关键参数（模式 1 - Sul1996） <a class="header-anchor" href="#关键参数-模式-1-sul1996" aria-label="Permalink to &quot;关键参数（模式 1 - Sul1996）&quot;">​</a></h2><p><code>_Tdead</code>（死区时间）、<code>_Vce0</code>（IGBT 导通压降）、<code>_Vd0</code>（二极管导通压降） ——在 main.c 中定义</p>',12)])])}const _=e(r,[["render",i]]);export{m as __pageData,_ as default};
